-- ============================================================================
-- GARMIN TRAINING HUB — MIGRAÇÃO 120: Reformula a aula "Portfólio de
-- Produtos" (lição MARQ) em treinamento de produto + vendas completo
-- ============================================================================
-- Pedido do usuário (2026-09-15): a 3ª (e última) lição do módulo "Portfólio
-- de Produtos" (Zona Explorador) só cobria a linha MARQ, de forma resumida.
-- O módulo tem só 3 lições (Forerunner, Fenix, MARQ, ver sql/030) — o
-- usuário decidiu concentrar TUDO nesta 3ª lição em vez de criar lições
-- novas: organização do portfólio, resumo de Forerunner/Fenix (que já têm
-- lição própria, aqui só recapitula), MARQ completo, e categorias que nunca
-- tinham conteúdo de treinamento nenhum (Edge, Varia, Rally, HRM, Blaze),
-- mais conceitos técnicos, raciocínio de venda, um quiz de associação
-- (tipo de bloco 'match_quiz', já existente e usado em outras lições — não
-- foi criado nada novo) e um quiz final.
--
-- Sem inventar dado: todo texto de produto (Forerunner, Fenix, Edge, Varia,
-- Rally, HRM) usa o `dest`/texto já cadastrado em content_library (categoria
-- 'produto', sql/seeds/040). O Blaze usa só os fatos já cadastrados na
-- Academia de Produtos (sql/090_academia_seed_hrm_blaze_cirqa.sql) — nenhuma
-- especificação nova foi adicionada, e propositalmente NÃO inclui "distância"
-- nem "recuperação" entre as métricas do Blaze por não estarem consistentes
-- nas duas fontes cadastradas (deep_dive vs. página da Academia).
--
-- O "Quiz Final" reaproveita o quiz já existente pra este módulo (slug
-- 'produtos', 10 perguntas — ver sql/097) via bloco 'quiz_embutido', em vez
-- de criar um quiz novo. Só ACRESCENTA (nunca remove/edita) 7 perguntas
-- novas testando raciocínio comercial sobre o conteúdo novo desta lição
-- (Rally, Varia, Blaze, Fenix, HRM, MARQ) — inserção pura, sem tocar nas 10
-- perguntas antigas, porque UPDATE/DELETE nelas arriscaria referências de
-- quiz_attempts/quiz_answers de quem já respondeu.
-- ============================================================================

do $$
declare
  v_quiz_id uuid;
  v_body jsonb;
  v_q_id uuid;
begin
  select id into v_quiz_id from quizzes
   where brand_id = (select id from brands where slug = 'garmin') and slug = 'produtos';

  if v_quiz_id is null then
    raise exception 'Quiz "produtos" não encontrado — rode sql/seeds/020_quizzes.sql antes desta migração.';
  end if;

  -- corpo da lição (17 seções do roteiro do usuário, quizId do bloco
  -- quiz_embutido preenchido dinamicamente com o id real do quiz acima)
  v_body := '[{"type":"texto_rico","html":"<h3>Conheça o portfólio Garmin</h3><p>Agora que você já aprendeu a identificar o perfil do cliente, é hora de conhecer as soluções Garmin.</p><p>A Garmin vai muito além dos relógios. O portfólio reúne produtos para corrida, triathlon, outdoor, ciclismo, natação, mergulho, golfe, navegação, sensores de performance e até soluções específicas para o monitoramento de cavalos.</p><p>O segredo não é decorar todos os produtos. É entender qual necessidade cada categoria atende.</p><p><strong>Primeiro entenda a necessidade. Depois pense no produto.</strong></p>"},{"type":"card_grid","columns":3,"items":[{"title":"Relógios esportivos","text":"Corrida, triathlon, outdoor e multiesporte.","tags":[]},{"title":"Ciclismo","text":"Ciclocomputadores, radares, sensores e medidores de potência.","tags":[]},{"title":"Natação e performance","text":"Sensores e acessórios para ampliar os dados dos treinos.","tags":[]},{"title":"Mergulho","text":"Computadores de mergulho e recursos específicos para atividades subaquáticas.","tags":[]},{"title":"Golfe","text":"Relógios e dispositivos desenvolvidos para o campo.","tags":[]},{"title":"Navegação","text":"Soluções para veículos, motos, barcos e atividades outdoor.","tags":[]},{"title":"Outras soluções","text":"Produtos específicos para necessidades diferentes, como o Garmin Blaze.","tags":[]}]},{"type":"texto_rico","html":"<h3>Relógios esportivos</h3><p>Os relógios Garmin são organizados em diferentes linhas porque os clientes também têm necessidades diferentes.</p><p>Um corredor iniciante não precisa necessariamente do mesmo produto que um triatleta de alta performance. Da mesma forma, quem pratica trilha, mergulho ou vários esportes pode precisar de recursos específicos.</p><ul><li><strong>Forerunner</strong> → corrida e triathlon</li><li><strong>Fēnix</strong> → multiesporte e outdoor</li><li><strong>MARQ</strong> → luxo + performance</li></ul><p>As linhas Forerunner e Fēnix você já viu em detalhe nas aulas anteriores. Aqui vai um resumo rápido antes de entrar na MARQ.</p>"},{"type":"texto_rico","html":"<h4>Forerunner: corrida e triathlon</h4><p>A linha Forerunner é a principal referência Garmin para quem tem a corrida como foco. Ela atende desde quem está começando até atletas que treinam e competem em alto nível. Na venda, pense primeiro no nível de experiência e no quanto o cliente quer evoluir no treinamento.</p>"},{"type":"card_grid","columns":3,"items":[{"title":"Forerunner 70","text":"GPS + cardíaco óptico + Garmin Pay. Design compacto e leve.","tags":[{"label":"Entrada","color":""}]},{"title":"Forerunner 55","text":"GPS + cardíaco óptico. Porta de entrada para quem começa a correr.","tags":[{"label":"Entrada","color":""}]},{"title":"Forerunner 165","text":"AMOLED + planos de treino adaptativos + treino de força.","tags":[{"label":"Intermediário","color":""}]},{"title":"Forerunner 170","text":"AMOLED + Elevate Gen 4. Mais compacto que o 165.","tags":[{"label":"Intermediário","color":""}]},{"title":"Forerunner 265","text":"AMOLED + GPS multibanda + Training Readiness.","tags":[{"label":"Intermediário avançado","color":""}]},{"title":"Forerunner 570","text":"GPS SatIQ + Elevate Gen 5. Treino intervalado preciso.","tags":[{"label":"Avançado","color":""}]},{"title":"Forerunner 955","text":"30h GPS + mapas topográficos + solar.","tags":[{"label":"Alta performance","color":""}]},{"title":"Forerunner 965","text":"AMOLED + titânio + mapas + 31h GPS.","tags":[{"label":"Alta performance","color":""}]},{"title":"Forerunner 970","text":"Cristal de safira + lanterna LED + 32GB.","tags":[{"label":"Topo de linha","color":""}]}]},{"type":"texto_rico","html":"<h4>Fēnix: multiesporte e outdoor</h4><p>O fēnix é indicado para quem quer um relógio preparado para muito mais do que corrida. É uma linha que combina treinamento, aventura, navegação e atividades outdoor em uma proposta premium. Na venda, pense no cliente que pratica diferentes esportes ou valoriza resistência, navegação e recursos avançados.</p>"},{"type":"card_grid","columns":3,"items":[{"title":"Fēnix E","text":"AMOLED + GPS padrão + mapas TopoActive. Robusto, sem alto-falante/mic e sem GPS multibanda.","tags":[{"label":"Entrada","color":""}]},{"title":"Fēnix 8","text":"O multiesporte definitivo. Alto-falante, mic, mergulho, trilha, corrida.","tags":[{"label":"Premium / Outdoor","color":""}]},{"title":"Fēnix 8 AMOLED Sapphire","text":"Cristal de safira para máxima resistência a arranhões, com acabamento premium — reúne todos os recursos do Fēnix 8.","tags":[{"label":"Premium","color":""}]}]},{"type":"texto_rico","html":"<h3>MARQ: luxo + performance</h3><p>A MARQ ocupa uma posição diferente dentro do portfólio.</p><p>Aqui, além da performance, entram materiais premium, acabamento, exclusividade e posicionamento de luxo. É uma linha para um cliente que não está procurando apenas funcionalidades — ele também valoriza a experiência e a presença do produto no pulso.</p><p><strong>Não apresente a MARQ apenas como um relógio com mais recursos.</strong> O diferencial está na combinação entre tecnologia Garmin, materiais premium e posicionamento de luxo.</p>"},{"type":"accordion","items":[{"title":"MARQ Commander (Gen 2) — para quem é, o que entrega, como apresentar","html":"<p><strong>Para quem é:</strong> cliente que combina alto desempenho com presença no pulso — quer tecnologia de ponta, mas também estética.</p><p><strong>O que entrega:</strong> caixa em titânio e pulseira em couro italiano, estética militar sofisticada, GPS multibanda, mapas completos e modo tático.</p><p><strong>O que diferencia:</strong> é o único da linha com essa estética tática/militar — combina robustez com acabamento de luxo.</p><p><strong>Como apresentar:</strong> na venda, pense em quem já usa ou usaria um Fēnix, mas quer um passo além em material e exclusividade.</p>"},{"title":"MARQ Athlete (Gen 2) — para quem é, o que entrega, como apresentar","html":"<p><strong>Para quem é:</strong> atleta de corrida e triathlon de alto nível que não abre mão de estilo.</p><p><strong>O que entrega:</strong> titânio com pulseira sport premium, GPS multibanda, métricas avançadas de treino e Training Readiness.</p><p><strong>O que diferencia:</strong> é a MARQ voltada especificamente para performance esportiva, não outdoor nem golfe.</p><p><strong>Como apresentar:</strong> pense nele como a opção para o cliente que já pensaria num Forerunner topo de linha, mas quer também exclusividade de material.</p>"},{"title":"MARQ Golfer Carbon (Gen 2) — para quem é, o que entrega, como apresentar","html":"<p><strong>Para quem é:</strong> golfista que valoriza tanto o jogo quanto o status do equipamento.</p><p><strong>O que entrega:</strong> caixa em fibra de carbono com acabamento premium, mapas de mais de 42.000 campos de golfe, modo caddie digital, estatísticas de jogo e distâncias automáticas.</p><p><strong>O que diferencia:</strong> é o único relógio de golfe no patamar de luxo real — não existe equivalente Approach com esse posicionamento.</p><p><strong>Como apresentar:</strong> não é só “um Approach mais caro” — é a opção de quem já joga com equipamento premium e quer o relógio à altura.</p>"}]},{"type":"texto_rico","html":"<h3>Garmin é muito mais do que relógios</h3><p>A conversa de venda não deveria terminar no relógio. Boa parte das oportunidades reais está nos acessórios e nas outras categorias do portfólio.</p>"},{"type":"card_grid","columns":3,"items":[{"title":"Ciclocomputadores — Edge","text":"Para quem quer levar os dados e a navegação para o guidão da bicicleta.","tags":[]},{"title":"Radares — Varia","text":"Para ciclistas que querem aumentar a percepção dos veículos que se aproximam por trás.","tags":[]},{"title":"Medidores de potência — Rally","text":"Para quem quer acompanhar o esforço produzido na pedalada em watts.","tags":[]},{"title":"Sensores cardíacos — HRM","text":"Para quem quer dados de frequência cardíaca mais específicos ou precisa ampliar os dados registrados pelo relógio.","tags":[]},{"title":"Mergulho — Descent","text":"Computadores de mergulho completos, com smartwatch fora da água.","tags":[]},{"title":"Golfe — Approach","text":"Distâncias automáticas e recursos de jogo direto no pulso.","tags":[]},{"title":"Navegação — GPSMAP / Zūmo","text":"Soluções específicas para trilha, náutica e viagens de moto.","tags":[]},{"title":"Monitoramento equino — Blaze","text":"Para cavaleiros, proprietários e treinadores que acompanham o desempenho do cavalo.","tags":[]}]},{"type":"texto_rico","html":"<h3>Edge: performance no guidão</h3><p>Os Edge são ciclocomputadores desenvolvidos para quem quer transformar a bicicleta em uma experiência mais completa de treinamento, navegação e performance.</p><p>Aqui, o raciocínio comercial é diferente dos relógios. Pergunte primeiro:</p><ul><li>O cliente pedala por lazer ou treina?</li><li>Usa estrada, MTB ou gravel?</li><li>Precisa de navegação?</li><li>Quer acompanhar potência e outros dados?</li><li>Pedala por longos períodos?</li></ul>"},{"type":"card_grid","columns":3,"items":[{"title":"Edge 540","text":"GPS multibanda + botões físicos. Bateria 26h. Compacto e preciso.","tags":[{"label":"Intermediário","color":""}]},{"title":"Edge 550","text":"Tela 1000 nits + speaker + Cycling Coach. Sucessor do 540.","tags":[{"label":"Intermediário","color":""}]},{"title":"Edge 840","text":"Touchscreen + botões + GPS multibanda + ClimbPro. Ideal para MTB e estrada.","tags":[{"label":"Dedicado","color":""}]},{"title":"Edge 850","text":"Tela 1000 nits + speaker + bike bell. Versão compacta do 1050.","tags":[{"label":"Dedicado / Avançado","color":""}]},{"title":"Edge 1040","text":"Tela 3.5\" + mapas + solar disponível. Bateria 35h+ GPS.","tags":[{"label":"Avançado","color":""}]},{"title":"Edge 1050","text":"Tela 3.5\" 1000 nits + Garmin Pay + buzina + alerta de perigo.","tags":[{"label":"Elite","color":""}]}]},{"type":"tabela","headers":["Modelo","Tier","O que muda"],"rows":[["Edge 550","Intermediário","Sucessor do 540 — soma tela de 1000 nits, speaker e Cycling Coach"],["Edge 850","Dedicado / Avançado","Versão compacta do 1050 — mesma tela de 1000 nits e speaker, sem o tamanho 3.5\""],["Edge 1050","Elite","Tela 3.5\" 1000 nits, Garmin Pay, buzina e alerta de perigo — topo absoluto da linha"]]},{"type":"accordion","items":[{"title":"Como identificar oportunidade de upgrade no Edge","html":"<p>Se o cliente já pedala com um Edge de entrada (540) e menciona querer navegação melhor, tela maior ou mais autonomia, vale apresentar o 1040 ou 1050.</p><p>Se ele valoriza tela grande e recursos de segurança (buzina, alerta de perigo) e anda em grupo ou no trânsito, o 1050 é o ponto natural de conversa.</p><p>Não empurre o topo de linha por padrão — pergunte primeiro o que o cliente já sente falta no equipamento atual.</p>"}]},{"type":"texto_rico","html":"<h3>Varia: segurança para o ciclista</h3><p>O Varia complementa a experiência de quem pedala na estrada ao adicionar recursos de percepção e segurança. O radar traseiro RTL515 detecta veículos a até 140 metros e alerta direto no relógio ou no Edge.</p><p><strong>Se o cliente já está comprando ou usando um Edge, pergunte se ele já utiliza algum recurso de segurança traseira.</strong> Essa é uma boa oportunidade de venda complementar — não trate o Varia como um simples acessório opcional.</p>"},{"type":"texto_rico","html":"<h3>Rally: potência no pedal</h3><p>Os pedais Rally (RK 200) são voltados para ciclistas que querem medir a potência produzida durante a pedalada — compatíveis com qualquer pedivela.</p><p>Pense em potência como uma forma de medir o esforço produzido pelo ciclista em watts: é uma métrica mais objetiva que percepção de esforço ou frequência cardíaca, e por isso interessa a quem já treina de forma mais estruturada.</p><p>Vale oferecer quando o cliente já fala em treino estruturado, zonas de esforço ou preparação para prova — não é um produto de entrada.</p>"},{"type":"texto_rico","html":"<h3>HRM: quando o relógio pode ganhar mais dados</h3><p>Os sensores cardíacos podem complementar o relógio Garmin, fornecendo dados de frequência cardíaca e, dependendo do modelo e da atividade, outras informações de desempenho.</p><p><strong>Se o cliente treina com frequência e busca dados mais específicos de esforço, vale investigar se um sensor cardíaco faz sentido.</strong> Não apresente o HRM apenas como \"uma cinta que mede batimentos\" — é uma oportunidade real de venda complementar.</p>"},{"type":"accordion","items":[{"title":"HRM 200 — quando oferecer","html":"<p><strong>Para quem é:</strong> corredor ou ciclista que quer mais precisão que o sensor óptico de pulso.</p><p><strong>Principal diferencial:</strong> monitor cardíaco de peito, com precisão superior ao óptico.</p><p><strong>Quando oferecer:</strong> quando o cliente treina em alta intensidade ou já reclamou de leitura instável no pulso.</p><p><strong>Como complementa o relógio:</strong> substitui a leitura óptica por uma leitura direto do peito, mais estável durante o esforço.</p>"},{"title":"HRM 600 — quando oferecer","html":"<p><strong>Para quem é:</strong> corredor, nadador ou triatleta que quer o pacote completo de dados.</p><p><strong>Principal diferencial:</strong> monitor cardíaco premium, com dinâmicas de corrida, HRV e armazenamento próprio.</p><p><strong>Quando oferecer:</strong> para quem já treina estruturado e quer métricas de corrida mais avançadas, inclusive na natação.</p><p><strong>Como complementa o relógio:</strong> grava a atividade mesmo debaixo d''água, ampliando o que o relógio sozinho conseguiria captar.</p>"}]},{"type":"texto_rico","html":"<h3>BLAZE: uma solução diferente dentro do portfólio Garmin</h3><p>Quando aparecer um cliente ligado à equitação, não pense automaticamente em relógio.</p><p>O Garmin Blaze é um sistema de monitoramento de bem-estar equino, desenvolvido para cavaleiros, proprietários e treinadores que querem acompanhar dados do cavalo durante o treinamento e outras atividades. Usa um sensor encaixado numa faixa posicionada na base da cauda do cavalo, e acompanha dados como frequência cardíaca, passada e andamento. Tem aplicativo próprio e pode mostrar dados em relógios Garmin compatíveis.</p><p>O Blaze abre uma conversa diferente: monitoramento do cavalo, treinamento e acompanhamento de dados — não é uma linha de relógios.</p><p><strong>Pergunta-chave:</strong> \"Você acompanha o desempenho do seu cavalo durante os treinos?\"</p>"},{"type":"card_grid","columns":1,"items":[{"title":"Garmin Blaze","text":"<strong>Para quem é:</strong> cavaleiros, proprietários e treinadores.<br><strong>O que resolve:</strong> monitoramento do cavalo durante treinamento e outras atividades.<br><strong>Diferencial:</strong> é uma solução Garmin específica para monitoramento equino, com sensor próprio e aplicativo dedicado.<br><strong>Como identificar a oportunidade:</strong> cliente ligado à equitação, treinamento de cavalos ou acompanhamento de desempenho equino.","tags":[{"label":"Linha Equina","color":""}]}]},{"type":"metric_card_grid","columns":2,"items":[{"icon":"⌚","name":"Relógio + HRM","definition":"Mais dados de frequência cardíaca e desempenho.","tip":"Pergunte se o cliente já sentiu leitura instável no pulso durante treino intenso."},{"icon":"🚴","name":"Edge + Varia","definition":"Computador de ciclismo + segurança.","tip":"Sempre pergunte sobre segurança pra quem pedala na rua ou estrada com tráfego."},{"icon":"⚡","name":"Edge + Rally","definition":"Navegação e dados de potência.","tip":"Vale quando o cliente já fala em treino estruturado ou preparação pra prova."},{"icon":"➕","name":"Relógio + acessórios","definition":"Expanda os dados e a experiência do cliente.","tip":"Produto principal + necessidade adicional = oportunidade de venda complementar."}]},{"type":"metric_card_grid","columns":2,"items":[{"icon":"📟","name":"AMOLED","definition":"Tipo de tela com cores vivas e alto contraste, parecida com a de um smartphone.","tip":"Explique como \"tela mais bonita e nítida\", mas lembre que costuma gastar mais bateria que telas mais simples."},{"icon":"🛰️","name":"GPS multibanda","definition":"Usa duas frequências de satélite ao mesmo tempo, em vez de uma só.","tip":"Diga que o traçado da rota fica muito mais preciso em cidade, mata ou perto de prédios altos."},{"icon":"🛰️","name":"SatIQ","definition":"Tecnologia que alterna automaticamente entre os modos de GPS pra economizar bateria sem perder precisão.","tip":"Explique como \"o relógio decide sozinho quanto de GPS usar\", sem o cliente precisar configurar nada."},{"icon":"🗺️","name":"Mapas","definition":"Cartografia embarcada no relógio ou dispositivo, sem precisar do celular.","tip":"Bom argumento pra quem faz trilha ou pedala em lugares sem sinal de internet."},{"icon":"🔋","name":"Body Battery","definition":"Indicador de energia do corpo, de 0 a 100, baseado em sono, estresse e atividade.","tip":"Explique como \"um medidor de pilha do seu corpo\", que ajuda a decidir quando treinar forte ou descansar."},{"icon":"📈","name":"Status de treinamento (Training Readiness)","definition":"Estimativa de o quanto o corpo está pronto pra treinar forte naquele dia.","tip":"Use pra clientes que treinam com frequência e querem entender quando forçar ou recuperar."},{"icon":"⚡","name":"Potência","definition":"Medição do esforço físico em watts, em vez de só velocidade ou frequência cardíaca.","tip":"É a métrica mais objetiva do ciclismo — não muda com cansaço, calor ou nervosismo do dia."},{"icon":"📍","name":"GPS","definition":"Sistema de posicionamento por satélite, usado pra registrar rota, distância e velocidade.","tip":"É a base de qualquer relógio ou dispositivo esportivo Garmin."},{"icon":"📡","name":"Radar","definition":"Sensor que detecta objetos se aproximando por trás, como carros numa estrada.","tip":"No Varia, isso vira um alerta visual e sonoro direto no relógio ou Edge do ciclista."},{"icon":"❤️","name":"Frequência cardíaca","definition":"Número de batimentos do coração por minuto, medido no pulso (óptico) ou no peito (HRM).","tip":"Explique que a leitura de peito costuma ser mais precisa em esforço alto que a do pulso."},{"icon":"💎","name":"Cristal de safira","definition":"Material de tela mais resistente a arranhões que o vidro comum.","tip":"Use como argumento de durabilidade pra quem usa o relógio no dia a dia intenso ou em trabalho manual."}]},{"type":"texto_rico","html":"<h3>Do produto para a necessidade</h3><p>Na prática, o raciocínio de venda segue sempre a mesma lógica:</p><p><strong>Cliente fala → você identifica a necessidade → escolhe a categoria → compara os modelos → apresenta o benefício → avalia uma venda complementar.</strong></p><p>Exemplo:</p><p>\"Cliente: quero melhorar meus treinos de bike.\"</p><p>Você pensa: ciclismo → Edge → entender nível de treino → ver necessidade de navegação → investigar potência → avaliar Varia / Rally.</p>"},{"type":"texto_rico","html":"<h4>Quiz de associação — aquecimento</h4><p>Antes do quiz final, relacione cada perfil de cliente com a linha ou produto certo.</p>"},{"type":"match_quiz","pairs":[{"term":"Corredor","definition":"Forerunner"},{"term":"Aventureiro","definition":"Fēnix"},{"term":"Cliente premium","definition":"MARQ"},{"term":"Ciclista que quer dados no guidão","definition":"Edge"},{"term":"Ciclista preocupado com segurança","definition":"Varia"},{"term":"Ciclista interessado em potência","definition":"Rally"},{"term":"Cliente buscando sensor cardíaco","definition":"HRM"},{"term":"Mergulhador","definition":"Descent"},{"term":"Golfista","definition":"Approach"},{"term":"Cliente ligado à equitação","definition":"Blaze"}]},{"type":"texto_rico","html":"<h4>Quiz final</h4><p>Agora teste seu raciocínio comercial com o quiz do módulo — as perguntas testam se você consegue reconhecer a categoria certa pra cada situação de cliente, não decorar especificação solta.</p>"},{"type":"quiz_embutido","quizId":"","label":"Responder quiz do módulo"}]'::jsonb;
  v_body := jsonb_set(v_body, '{-1,quizId}', to_jsonb(v_quiz_id::text));

  update lessons
     set body = jsonb_build_object('blocks', v_body),
         updated_at = now()
   where id = '7d5e81d0-21a1-426a-9938-7bb667723d3c';

  if not found then
    raise exception 'Lição MARQ (id 7d5e81d0-...) não encontrada — verifique se sql/030 já foi aplicada.';
  end if;

  -- 7 perguntas novas no quiz do módulo, cobrindo o conteúdo novo desta
  -- lição (Rally, Varia, Blaze, Fenix, HRM, MARQ) — puro INSERT, não mexe
  -- nas 10 perguntas existentes (Forerunner/Fenix/MARQ já cobertas por
  -- sql/097). order_index continua depois da última (9).

  insert into questions (quiz_id, body, explanation, order_index)
  values (v_quiz_id, 'Um cliente diz que corre três vezes por semana e quer começar a acompanhar melhor sua evolução. Qual linha deve ser considerada primeiro?', 'Corrida com frequência regular e interesse em evolução é o perfil clássico de Forerunner — o próximo passo é entender se ele já usa GPS pra escolher entre entrada e intermediário.', 10)
  returning id into v_q_id;
  insert into alternatives (question_id, body, is_correct, feedback, order_index) values (v_q_id, 'Forerunner', true, null, 0);
  insert into alternatives (question_id, body, is_correct, feedback, order_index) values (v_q_id, 'Fēnix', false, null, 1);
  insert into alternatives (question_id, body, is_correct, feedback, order_index) values (v_q_id, 'MARQ', false, null, 2);
  insert into alternatives (question_id, body, is_correct, feedback, order_index) values (v_q_id, 'Edge', false, null, 3);

  insert into questions (quiz_id, body, explanation, order_index)
  values (v_quiz_id, 'Um cliente já possui um Garmin e está treinando para uma prova de ciclismo. Ele quer acompanhar potência. Qual oportunidade deve ser investigada?', 'Potência em watts é exatamente o que o Rally mede — é uma venda complementar a um Edge ou relógio que o cliente já tenha.', 11)
  returning id into v_q_id;
  insert into alternatives (question_id, body, is_correct, feedback, order_index) values (v_q_id, 'Rally', true, null, 0);
